command.source:
M19MAKE() BEGIN A:=A+1; RETURN 1/0; END;
LOCAL count:=M19MAKE();
EXPORT M19READ() BEGIN RETURN count; END;

EXPORT M19RAT() BEGIN RETURN CAS("1/3"); END;
EXPORT M19SYM() BEGIN RETURN CAS("x+1"); END;
EXPORT M19NEST() BEGIN RETURN {{1+2*i,3-4*i},{5}}; END;
EXPORT M19INT() BEGIN RETURN #FFFFFFFFFFFFFFFF:64h; END;
